import{_ as t,a,c as r,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"漫画算法","description":"通过图解、例题和状态变化进入算法学习，附待核对版本说明。","frontmatter":{"title":"漫画算法","description":"通过图解、例题和状态变化进入算法学习，附待核对版本说明。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 计算机与软件工程 · 数据结构、算法与软件设计","summary":"通过图解、例题和状态变化进入算法学习，附待核对版本说明。","status":"active","related":[{"title":"数据结构导论","link":"/life/personal/books/computing/data-structures","kind":"书籍导读","scope":"general","audience":"general"},{"title":"算法导论（原书第3版）","link":"/life/personal/books/computing/introduction-to-algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"程序员的数学","link":"/life/personal/books/computing/programmers-math","kind":"书籍导读","scope":"general","audience":"general"},{"title":"重构 改善既有代码的设计（第2版）","link":"/life/personal/books/computing/refactoring","kind":"书籍导读","scope":"general","audience":"general"}],"prev":{"text":"算法导论（原书第3版）","link":"/life/personal/books/computing/introduction-to-algorithms"},"next":{"text":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"算法导论（原书第3版）","link":"/life/personal/books/computing/introduction-to-algorithms"},"next":{"text":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms"}},"headers":[],"relativePath":"life/personal/books/computing/comic-algorithms.md","filePath":"life/personal/books/computing/comic-algorithms.md"}'),i={name:"life/personal/books/computing/comic-algorithms.md"};function l(n,e,s,d,h,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="漫画算法" tabindex="-1">漫画算法 <a class="header-anchor" href="#漫画算法" aria-label="Permalink to &quot;漫画算法&quot;">​</a></h1><p><a href="./../overview">返回分类书单</a></p><p><strong>分类：计算机与软件工程 / 数据结构、算法与软件设计</strong></p><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p>这本书在书单中适合承担算法的趣味入门角色。图解与故事式讲解可以降低第一次接触抽象结构的门槛，让读者看到数据在每一步怎样变化，再逐渐进入代码与复杂度分析。</p><p>建议把它作为进入严谨教材的桥梁。理解图示之后，亲自写出小实现、给出反例，并补充边界条件，才能把“看懂了”推进为“能够使用”。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p><strong>版本待确认。</strong> 书单只提供《漫画算法》，没有副标题、作者、卷次或 ISBN，不能直接把某一部续作或合集的目录当作本书目录。以下为本站主题导读，不是原书目录。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p>《漫画算法》尚未确认副标题、作者与卷次。可核对的候选是“程序员小灰”的《漫画算法：小灰的算法之旅》系列；作者在其署名文章中介绍过以漫画讲解算法和成书的过程。这能说明候选作者的技术传播方向，不能据此认定本册就是首册或某种语言版，也不能把传播影响力等同于每项技术结论的正确性。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合对算法有兴趣、却暂时被抽象定义和长代码劝退的读者。已有语言基础者读后应自己实现；需要系统证明、复杂性理论或完整课程训练的人，还需配合更严谨的教材。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>导读主题</th><th>阅读与练习重点</th></tr></thead><tbody><tr><td>算法与复杂度</td><td>通过规模增长观察操作数量，理解时间和空间成本的含义。</td></tr><tr><td>基本数据结构</td><td>为数组、链表、栈和队列画状态图，解释每次操作修改了什么。</td></tr><tr><td>树与层次关系</td><td>练习递归、遍历和堆，观察结构性质如何约束操作顺序。</td></tr><tr><td>排序过程</td><td>用同一组数字演示不同排序，比较稳定性、交换次数和额外空间。</td></tr><tr><td>典型算法问题</td><td>从暴力方案开始寻找重复工作，再考虑双指针、递归或动态规划等思路。</td></tr><tr><td>实际应用与表达</td><td>将一道题的输入、约束、方法和复杂度讲清楚，避免只记最终代码。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p>以下为本站阅读评析，用可实践的阅读目标表达收获，不代表书单提供者已经读完、任职或完成相应项目。版本未明时，评析只针对本页明确标注的主题或参考版本。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><blockquote><p>图解帮人看见过程，反例帮人看见条件。</p></blockquote><p>这是本站原创阅读提炼，不是原书引文；没有可核对页码的原文不作逐字摘抄。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p>对照一张排序或链表操作图，先遮住下一步自己预测，再换成重复值、空表或单节点。能解释这些边界下的状态变化，才说明图像记忆开始变成可实现的规则。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>漫画形式降低阅读门槛，但少量演示元素很难展示所有边界，趣味也不能代替证明。具体语言和章节范围待版本确认；建议用“画图—口述不变量—编码—构造反例”补全学习过程。</p><p><strong>推荐语（本站原创，非原书引用）：</strong> 推荐作为算法入门的台阶：愿意在每个故事之后多写一个反例，收益会比只记住故事更长久。</p><h2 id="来源与核对入口" tabindex="-1">来源与核对入口 <a class="header-anchor" href="#来源与核对入口" aria-label="Permalink to &quot;来源与核对入口&quot;">​</a></h2><ul><li>书名来自本次书单；需补充副标题、作者和卷次后核对准确目录。</li><li><a href="https://visualgo.net/zh" target="_blank" rel="noopener noreferrer">VisuAlgo</a>：数据结构与算法可视化补充练习，不是本书内容或目录来源。</li><li><a href="https://opendatastructures.org/" target="_blank" rel="noopener noreferrer">Open Data Structures</a>：用于进一步学习实现和分析。</li><li><a href="https://www.sohu.com/a/340480380_684445" target="_blank" rel="noopener noreferrer">程序员小灰署名自述：成书过程</a>：仅用于候选作者的写作背景，不作本册版次和目录证据。</li></ul>',26)])])}const g=t(i,[["render",l]]);export{u as __pageData,g as default};
